from pathlib import Path
import json
P=Path(__file__).resolve().parent;E=P.parent/'bill-drink-east-coherent-v1'
entry=json.loads((P/'manifest.json').read_text())['states'];loop=json.loads((E/'manifest.json').read_text())['states'][0]
states=[]
for root,state in [(P,entry[0]),(E,loop),(E,loop),(P,entry[1])]:states.append({'files':['/'+(root/f).relative_to(P.parent.parent).as_posix() for f in state['frameFiles']],'durations':state['frameDurationsMs']})
html='''<!doctype html><meta charset="utf-8"><title>Bill east cup pickup and return</title><style>body{font:16px system-ui;background:#152027;color:#e6eff1;margin:24px}button,select{font:inherit;padding:6px}p{max-width:85ch;color:#bdd0d2}</style><h1>Bill — east cup pickup, eat and return</h1><p>Left: candidate pickup/two drinking cycles/reversed return. Right: selected idle master. Exact empty/held endpoints, progressive short reach and planted feet. Preview timing only; cup transitions and normal drink service integration remain pending.</p><select id="size"><option>148</option><option>82</option><option>54</option></select><button id="play">Pause</button><canvas id="view" width="720" height="420"></canvas><script>const data=DATA;let time=0,last=performance.now(),playing=true;play.onclick=()=>{playing=!playing;play.textContent=playing?'Pause':'Play'};const load=f=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=reject;im.src=f});Promise.all(data.map(async s=>s.images=await Promise.all(s.files.map(load)))).then(()=>{function draw(now){if(playing)time+=now-last;last=now;const c=view.getContext('2d'),scale=Number(size.value)/148,images=data.flatMap(s=>s.images),durations=data.flatMap(s=>s.durations);let t=time%durations.reduce((a,b)=>a+b,0),index=0;for(let i=0;i<images.length;i++){index=i;if(t<durations[i])break;t-=durations[i]}c.fillStyle='#22343e';c.fillRect(0,0,720,420);c.drawImage(images[index],200-128*scale,330-224*scale,256*scale,256*scale);c.drawImage(images[0],520-128*scale,330-224*scale,256*scale,256*scale);requestAnimationFrame(draw)}requestAnimationFrame(draw)});</script>'''
html=html.replace('pickup, eat and return','pickup, drink and return').replace('cup transitions and normal drink service integration remain pending','normal meal service integration remains pending')
(P/'index.html').write_text(html.replace('DATA',json.dumps(states)))
print('Built source-bound pickup/drink/return candidate preview')
